from typing import List

def merge_intervals_strict(intervals: List[List[int]]) -> List[List[int]]:
    if not intervals:
        return []

    intervals.sort(key=lambda x: x[0])
    merged = []
    start, end = intervals[0]

    for i in range(1, len(intervals)):
        current = intervals[i]
        if current[0] <= end:
            end = max(end, current[1])
        else:
            merged.append([start, end])
            start, end = current

    merged.append([start, end])
    return merged

def spiral_order_ccw(matrix):
    if not matrix or not matrix[0]:
        return []

    m = len(matrix)
    n = len(matrix[0])

    result = []
    left, right = 0, n - 1
    top, bottom = 0, m - 1

    while left <= right and top <= bottom:
        # Traverse the top row from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])

        top += 1

        # Traverse the right column from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])

        right -= 1

        # Check if there are any rows left to traverse
        if top <= bottom:
            # Traverse the bottom row from right to left
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])

            bottom -= 1

        # Check if there are any columns on the left side
        if left <= right:
            # Traverse the left column from bottom to top
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])

            left += 1

    return result

def longest_unique_substring_text(s):
    char_index_map = {}
    start = maxLength = 0

    for end, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1

        char_index_map[char] = end
        maxLength = max(maxLength, end - start + 1)

    return s[start:start + maxLength]
